"""Explain per-CPU reader attempts, waiting and release."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1417': ('도서관에 지금 들어갈 수 있는지 한 번 시도합니다. 들어가지 못했다면 퇴장 인원을 또 빼면 안 됩니다.', '읽기 trylock의 성공·실패와 대응 반납을 구별합니다.', '성공 true → 자료 읽기 → up_read, 실패 false → 읽기 보유 없음 → up_read 없음으로 두 줄을 그리세요.', ['percpu_down_read_trylock은 읽기 사용권을 시도하고 참·거짓을 돌려줍니다. 일반 down_read와 달리 바로 얻지 못한 경우 대기열에서 잠들어 기다리지 않고 실패할 수 있습니다.', '처음 ret는 true입니다. preempt_disable로 경로 선택과 현재 CPU 카운터 접근을 보호한 뒤 rss가 idle인지 봅니다. idle이면 this_cpu_inc로 현재 CPU의 읽기 기록을 하나 늘립니다.', 'idle이 아니면 __percpu_down_read(sem,true)의 결과를 ret에 담습니다. 두 번째 인자 true는 시도만 하겠다는 뜻입니다. 별도 경로에서 차단 상태를 보면 임시 증가를 되돌린 뒤 false를 돌려줄 수 있습니다.', '그다음 preempt_enable로 이번 선점 금지를 되돌립니다. ret가 true일 때만 rwsem_acquire_read를 호출해 분석 도구에 성공한 읽기 획득을 기록합니다. 분석 기록이 먼저 권한을 만들어 주는 것은 아닙니다.', 'false면 읽기 사용권을 얻지 못했습니다. 이 실패를 정리한다고 up_read를 부르면 이미 취소한 인원을 다시 빼는 잘못이 됩니다. 성공 true인 경우만 자료를 보호 아래 읽고 나중에 한 번 반납합니다.', '반환 전에 선점 금지가 복구되어도 성공한 읽기 사용권은 up_read까지 유지됩니다. 선점 제어, 인원 카운터, 분석 기록을 각각 구별해 추적하세요. 이 조회·획득 함수가 객체 자체의 저장 공간 수명까지 자동 보장하지는 않습니다.'], [('trylock이 false이면 균형을 맞추려고 up_read를 해야 할까요?', ['네. 언제나 한 번 반납해야 해요', '아니요. 얻은 읽기 사용권이 없어요'], '실패 경로가 임시 증가를 이미 취소합니다. 추가 up_read는 들어오지 않은 독자의 퇴장을 기록하는 셈이라 카운터를 망가뜨립니다.'), ('분석 도구의 읽기 획득 기록은 실패 때도 남길까요?', ['아니요. ret가 true일 때만 기록해요', '네. 반환값과 무관하게 항상 기록해요'], '원문이 if (ret) 안에서 rwsem_acquire_read를 호출합니다. 실제로 획득하지 않은 실패 경로에는 보유 기록을 남기지 않습니다.')]), 'os1418': ('입장 인원을 먼저 한 명 올린 다음 문이 닫혔는지 확인합니다. 문이 닫혔다면 방금 올린 인원을 취소하고 기다리는 관리자에게 다시 확인하라고 알립니다.', '느린 읽기 시도의 증가·순서 보장·차단 검사·취소를 이해합니다.', '현재 CPU 카운터가 2라고 쓰세요. 임시 증가로 3, block=1 확인 뒤 취소로 2, writer 깨우기 순서로 표시하세요.', ['__percpu_down_read_trylock은 내부 helper입니다. 정해진 선점 금지 문맥에서 현재 CPU의 read_count를 먼저 하나 늘립니다. 이 증가는 아직 최종 진입 성공을 뜻하지 않습니다.', '다음 smp_mb는 메모리 배리어입니다. 앞의 증가와 뒤의 차단 상태 확인이 필요한 순서로 다른 CPU와 맞물리도록 합니다. 단순한 시간 지연이나 잠자기 명령은 아닙니다.', '그 뒤 atomic_read_acquire로 block을 읽습니다. 0이면 진입 가능하여 true를 반환합니다. acquire는 writer가 release로 block을 풀 때의 데이터 접근과 올바르게 이어지는 순서를 제공하는 읽기 방식입니다.', 'block이 1이면 this_cpu_dec로 방금 증가를 취소합니다. 이 짧은 시도 동안 선점이 금지되어 증가와 취소가 같은 CPU 기록에서 일어납니다. 처음 2였으면 3을 거쳐 다시 2가 됩니다.', '취소한 뒤 rcuwait_wake_up으로 기다리는 writer에게 독자 수를 다시 살펴보라고 알리고 false를 반환합니다. 깨운다는 것이 writer의 쓰기 진입을 무조건 허가한다는 뜻은 아닙니다. 실제 조건은 writer가 다시 확인합니다.', '독자가 차단 설정을 못 봤다면 writer가 독자의 증가를 보아야 하고, writer가 늦게 들어온 증가를 못 봤다면 그 독자가 차단을 보고 취소해야 합니다. reader의 A 배리어와 writer의 D 쪽 순서가 이 규칙을 만듭니다. 양쪽이 서로를 놓친 채 동시에 들어가지 못하게 하는 설계입니다.'], [('block=1을 본 독자의 임시 카운터 증가는 어떻게 될까요?', ['writer가 끝날 때까지 반드시 남아요', '같은 CPU에서 취소되어 원래 값으로 돌아가요'], '실패 경로가 this_cpu_dec를 수행합니다. 2→3→2 예시처럼 진입하지 않은 독자의 기록을 남기지 않습니다.'), ('진입에 성공하는 느린 경로는 block을 어떤 방식으로 읽을까요?', ['atomic_read_acquire로 읽어요', 'block을 전혀 읽지 않아요'], '원문이 acquire 읽기의 결과가 0인지 검사합니다. writer의 release 해제와 연결해 쓰기 결과를 올바른 순서로 읽기 위한 단계입니다.')]), 'os1419': ('입장 시도만 하는 사람은 문이 닫혔으면 돌아갑니다. 반드시 들어가야 하는 사람은 대기 명단에서 차례를 기다립니다. 두 요청은 같은 실패 뒤에도 다음 행동이 다릅니다.', '시도 실패와 대기 경로, 대기 전후 선점 상태를 이해합니다.', '바깥에서 선점 금지 0→1, 시도 실패 후 대기 전 1→0, 획득 후 0→1, 바깥 반환 전 1→0 순서로 적으세요. 이는 처음 잠들 수 있는 정상 문맥의 예입니다.', ['__percpu_down_read는 먼저 내부 trylock으로 즉시 획득을 시도합니다. 성공하면 바로 true입니다. 실패했을 때 인자 try가 true이면 대기하지 않고 false로 돌아갑니다.', 'try가 false이면 일반 읽기 획득 요청이므로 기다릴 수 있습니다. trace_contention_begin으로 경쟁 대기 시작을 기록하고 preempt_enable을 호출합니다. wrapper가 더했던 선점 금지를 대기 전에 되돌리는 것입니다.', 'percpu_rwsem_wait(sem,true)는 독자로서 진입을 기다리는 절차입니다. 내부에서 다시 바로 얻을 수도 있고, 못 얻으면 대기열에 들어가 잠들 수 있습니다. 처음부터 잠들 수 있는 올바른 호출 문맥이어야 합니다.', '잠든 경우 깨우는 함수는 실제 읽기 획득 시도에 성공한 뒤 완료 표시를 공개하고 작업을 깨웁니다. 대기 쪽은 그 완료 표시를 확인합니다. 단순히 어떤 깨우기 신호를 받았다는 사실만으로 임의로 획득 성공을 선언하는 것이 아닙니다.', '기다림을 마치면 preempt_disable을 다시 호출해 내부 helper 진입 때의 깊이를 맞춥니다. 경쟁 종료 기록을 남기고 true를 반환합니다. 바깥 wrapper가 마지막 enable을 하므로 전체가 균형을 이룹니다.', '원래 잠들면 안 되는 atomic 문맥에 있었다면 한 번 enable한다고 정상 대기 문맥이 되는 것은 아닙니다. 이 코드는 바깥 API의 올바른 사용 조건 아래 작동합니다. 내부 helper만 떼어 임의의 문맥에서 직접 사용하지 마세요.'], [('일반 느린 읽기 경로는 wrapper가 추가한 선점 금지를 유지한 채 잠들까요?', ['네. 추가 금지를 풀지 않고 대기해요', '아니요. 대기 전에 enable, 대기 후 disable을 해요'], '잠들 수 있는 대기 앞에서 이번 내부 금지를 되돌리고 이후 다시 맞춥니다. 바깥 wrapper의 금지·복구까지 함께 읽어야 합니다.'), ('try=true이고 즉시 획득에 실패하면 반드시 대기열에서 잠들까요?', ['아니요. false를 반환해요', '네. 모든 실패는 무조건 기다려요'], 'if (try) return false가 대기 코드보다 앞에 있습니다. 시도만 하는 요청과 반드시 획득하는 요청은 실패 후 행동이 다릅니다.')]), 'os1420': ('독서가 끝났다는 기록을 지우기 전에 책을 다 읽는 작업이 끝났음을 맞춰야 합니다. 기다리던 수정 담당자에게는 인원을 다시 확인하라고 알립니다.', '읽기 반납의 배리어·감소·writer 깨우기 순서를 이해합니다.', '느린 상태의 반납을 자료 사용 완료 → smp_mb → 현재 CPU 카운터 감소 → writer 깨우기 순서로 그리세요.', ['percpu_up_read는 성공적으로 얻은 읽기 사용권 하나를 반납합니다. trylock 실패 후 호출하거나 한 획득에 두 번 호출하면 안 됩니다. 분석 도구에 해제를 알린 뒤 잠깐 선점을 금지합니다.', 'rss가 idle이면 현재 CPU의 read_count를 하나 줄입니다. 읽기 획득 뒤에는 선점이 가능했으므로 이 정상 반납이 언제나 획득한 CPU에서 일어난다고 가정하면 안 됩니다. writer는 CPU별 기록의 합을 바탕으로 판단합니다.', 'rss가 idle이 아니면 먼저 smp_mb를 수행합니다. 원문에서는 B 배리어라고 표시하며, writer가 합계를 보고 사용하는 C 배리어와 연결됩니다. 독자의 자료 접근과 끝났다는 카운터 표시의 순서를 맞추는 역할입니다.', '그 뒤 this_cpu_dec로 현재 CPU 카운터를 줄이고 rcuwait_wake_up(&sem->writer)를 호출합니다. writer가 마지막 감소를 보았다면 앞선 읽기 구간의 접근도 끝난 것으로 순서가 맞아야 하므로 배리어가 감소보다 앞에 있습니다.', '깨우기 대상은 활동 중 독자가 끝나기를 기다리는 writer의 rcuwait입니다. 모든 CPU 작업을 한꺼번에 깨우는 함수가 아닙니다. 입장 대기열 sem->waiters를 깨우는 것과도 역할이 다릅니다.', '마지막 preempt_enable로 이번 금지를 되돌립니다. 카운터 감소가 객체 메모리를 직접 반납하는 것은 아닙니다. 읽기·쓰기 배제 규칙과 구조체 자체의 수명 관리는 별도로 지키고, 수 계산 예시만으로 실제 하드웨어 메모리 순서까지 검증했다고 생각하지 마세요.'], [('느린 읽기 반납은 카운터를 줄이기 전에 무엇을 할까요?', ['항상 카운터 전체를 먼저 0으로 덮어요', 'smp_mb를 수행해요'], 'B 배리어 뒤 this_cpu_dec가 나옵니다. 읽기 구간의 접근이 끝났다는 사실과 감소 관측의 순서를 연결하며, 다른 독자 기록까지 0으로 지우는 것은 아닙니다.'), ('이 느린 반납이 깨우는 대상은 무엇일까요?', ['기다리는 writer의 rcuwait예요', '언제나 모든 CPU의 모든 작업이에요'], '코드는 rcuwait_wake_up(&sem->writer)입니다. 독자 수를 다시 검사할 단일 쓰기 대기자를 위한 알림이며 전체 작업 깨우기가 아닙니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_350.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
